    emergency: 'ER',
    cticu: 'CT ICU',
    'ct icu': 'CT ICU',
    'cardiac icu': 'CT ICU',
    'ctvs icu': 'CT ICU',
    homecare: 'HomeCare',
    'home care': 'HomeCare',
    'family medicine': 'HomeCare',
    daycare: 'DayCare',
    'day care': 'DayCare'
